    // a triangle wave, -1..1, one period per unit: the shake
    public static float Tri(float v)
    {
        float f = v - (int)v;
        if (f < 0f) f = f + 1f;
        if (f < 0.5f) return f * 4f - 1f;
        return 3f - f * 4f;
    }

