    public static float ShakeX(float t)
    {
        float s = 0f;
        if (t >= 26f && t < 28f) s = s + 0.22f * Tri(t * 23f);
        return s;
    }

    public static float ShakeY(float t)
    {
        float s = 0f;
        if (t >= 26f && t < 28f) s = s + 0.22f * Tri(t * 31f + 0.3f);
        return s;
    }

    // the camera centre (cells) and zoom at t: the keys, shaken and punched
    public static float CamX(float t) { return CamBaseX(t) + ShakeX(t); }
    public static float CamY(float t) { return CamBaseY(t) + ShakeY(t); }
    public static float CamZoom(float t) { return CamBaseZoom(t) * Punch(t); }

